#!/usr/bin/env python3
"""Export a portable offline HTML catalog from the application content."""
from pathlib import Path
import json
import base64
import argparse
from datetime import datetime
from zoneinfo import ZoneInfo
parser=argparse.ArgumentParser(description='Export the application signs and numbered road markings as a self-contained HTML catalog.')
parser.add_argument('--output',default='output/pdd-signs-and-markings.html')
args=parser.parse_args()
root=Path(__file__).resolve().parents[2];assets=root/'assets/countries/ru';cards=[]
def datauri(p):
 mime='image/svg+xml' if p.suffix=='.svg' else 'image/png'
 return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def add(kind,category,number,title,description='',image=None,folk='',filename=''):
 cards.append(dict(kind=kind,category=category,number=number,title=title,description=description,image=datauri(image) if image else '',folk=folk,filename=filename))
for group,entries in json.loads((assets/'questions/signs.json').read_text()).items():
 for number,s in entries.items():add('sign',group,number,s['title'],s.get('description',''),assets/s['image'].removeprefix('./'),s.get('folkName',''))
for group,entries in json.loads((assets/'questions/markup.json').read_text()).items():
 for s in entries:add('marking',group,s['number'],s['title'],s['description'],assets/s['image'].removeprefix('./'))
counts={kind:sum(s['kind']==kind for s in cards) for kind in ['sign','marking']}
payload=json.dumps(cards,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
page=r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Знаки и разметка — ПДД Россия</title>
<style>
:root{color-scheme:light;--ink:#15233b;--muted:#63718a;--blue:#1769e0;--bg:#f3f6fb;--line:#dce4ef}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}button,input,select{font:inherit}button,select,summary{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #70aaff;outline-offset:3px}header{max-width:1480px;margin:auto;padding:38px 30px 24px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--blue)}h1{font-size:clamp(27px,4vw,40px);line-height:1.15;letter-spacing:-.035em;margin:12px 0}header p{margin:10px 0 0;color:var(--muted)}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.stat{background:white;border-radius:10px;padding:8px 13px;color:var(--muted)}.stat b{color:var(--ink);font-size:18px;margin-right:5px}.toolbar{position:sticky;top:0;z-index:5;background:#f3f6fbf5;backdrop-filter:blur(10px);border-block:1px solid var(--line)}.controls{max-width:1480px;margin:auto;padding:14px 30px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}.tabs{display:flex;background:#e5ebf5;padding:4px;border-radius:12px}.tab{border:0;background:transparent;color:var(--muted);padding:8px 15px;border-radius:9px;font-weight:600;white-space:nowrap}.tab[aria-pressed=true]{background:var(--blue);color:white}input,select{min-height:44px;border:1px solid var(--line);border-radius:10px;background:white;color:var(--ink);padding:9px 12px}input{flex:1;min-width:210px}select{max-width:310px}.action{border:1px solid var(--line);border-radius:10px;padding:9px 14px;background:white;color:var(--ink);min-height:44px}.statusbar{max-width:1480px;margin:auto;padding:16px 30px 0;display:flex;gap:16px;justify-content:space-between;align-items:center;color:var(--muted);font-size:13px}.check{display:flex;align-items:center;gap:7px;white-space:nowrap}.check input{width:16px!important;height:16px;min-height:0;min-width:0;flex:none;padding:0;margin:0;accent-color:var(--blue)}main{max-width:1480px;margin:auto;padding:8px 30px 50px}section{scroll-margin-top:100px}h2{font-size:22px;letter-spacing:-.02em;margin:27px 0 15px}.count{font-size:13px;font-weight:500;color:var(--muted);margin-left:8px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px}.card{background:white;border:1px solid #e5ebf3;border-radius:16px;padding:16px;min-width:0;align-self:start}.imagebutton{width:100%;height:150px;border:0;border-radius:10px;background:#f9fafc;display:flex;align-items:center;justify-content:center;padding:12px;cursor:zoom-in}.imagebutton img{display:block;width:100%;height:100%;object-fit:contain}.badge{font-weight:750;letter-spacing:.03em;color:var(--blue);font-size:14px;margin-top:13px}.card h3{font-size:15px;line-height:1.4;margin:5px 0 0}.folk{color:var(--muted);font-size:12px;margin:7px 0 0}.card details{margin-top:13px;border-top:1px solid #edf0f6;padding-top:10px}.card summary{font-size:13px;color:var(--blue)}.description{font-size:13px;color:#47566f;white-space:pre-line;overflow-wrap:anywhere;margin:10px 0 0}.filename{font:11px/1.5 ui-monospace,monospace;overflow-wrap:anywhere;color:var(--muted);margin-top:10px}.topic{padding:20px}.topic h3{font-size:17px}.topic .description{font-size:14px}.note{margin:20px 0 2px;padding:16px 20px;background:#e8effa;color:#405574;border-radius:12px;font-size:13px}.note strong{color:#213c65}.empty{text-align:center;padding:70px 20px;color:var(--muted)}[hidden]{display:none!important}footer{font-size:12px;color:var(--muted);padding:25px 0;border-top:1px solid var(--line);margin-top:35px}dialog{border:0;border-radius:20px;padding:0;width:min(740px,calc(100% - 24px));max-height:90vh;color:var(--ink)}dialog::backdrop{background:#15233ba6}.dialogbody{padding:28px;overflow:auto;max-height:90vh}.close{float:right;position:sticky;top:0;border:0;border-radius:50%;width:38px;height:38px;background:#eaf0f8;font-size:24px}.largeimage{display:block;max-width:100%;width:100%;height:320px;object-fit:contain;margin:25px auto}.dialogbody h2{margin:10px 0}.dialogbody .description{font-size:15px}body:has(dialog[open]){overflow:hidden}@media(max-width:680px){header{padding:25px 16px 20px}.controls{padding:10px 16px;gap:8px}.tabs{width:100%;justify-content:space-between}.tab{flex:1;padding:7px 10px}input{min-width:0;width:100%;flex-basis:100%}select{flex:1;min-width:0;max-width:none}.statusbar{padding:12px 16px 0}main{padding-inline:16px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.card{padding:12px;border-radius:12px}.imagebutton{height:130px;padding:8px}.card h3{font-size:13px}.grid:has(.topic){grid-template-columns:1fr}.dialogbody{padding:20px}.largeimage{height:240px}}@media print{body{background:white}.toolbar,.statusbar,.imagebutton:after,.note,dialog,footer{display:none!important}header{padding:0}main{padding:0}.stats{margin-bottom:20px}.grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.card{break-inside:avoid;border:1px solid #ddd}.card summary{display:none}section{break-before:auto}h2{break-after:avoid}.imagebutton{height:110px}.description{font-size:10px}h1{font-size:28px}}
</style></head><body>
<header><div class="eyebrow">ПДД Россия · Каталог приложения</div><h1>Дорожные знаки и разметка</h1><p>Все изображения и тексты собраны из локальной базы приложения. Файл работает без интернета.</p><div class="stats"><span class="stat"><b>__SIGN_COUNT__</b> знаков</span><span class="stat"><b>__MARKING_COUNT__</b> видов разметки</span></div></header>
<div class="toolbar"><div class="controls"><div class="tabs" role="group" aria-label="Тип материалов"><button class="tab" data-mode="all" aria-pressed="true">Всё</button><button class="tab" data-mode="sign" aria-pressed="false">Знаки</button><button class="tab" data-mode="markup" aria-pressed="false">Разметка</button></div><input id="search" type="search" placeholder="Номер, название или слово из описания…" aria-label="Поиск по каталогу"><select id="category" aria-label="Категория"><option value="">Все категории</option></select><button id="print" class="action">Печать</button></div></div>
<div class="statusbar"><span id="status" aria-live="polite"></span><label class="check"><input id="descriptions" type="checkbox"> Все описания</label></div>
<main><div id="sections"></div><div id="empty" class="empty" hidden>Ничего не найдено. Попробуйте другой номер или слово.</div><footer>Снимок базы приложения от __DATE__. Нажмите на изображение, чтобы увеличить его. Для поиска по описаниям не нужно их раскрывать.</footer></main>
<dialog id="zoom" aria-labelledby="zoom-title"><div class="dialogbody"><button class="close" aria-label="Закрыть">×</button><div id="zoom-number" class="badge"></div><h2 id="zoom-title"></h2><img class="largeimage" id="zoom-image" alt=""><p id="zoom-folk" class="folk"></p><p id="zoom-description" class="description"></p><p id="zoom-file" class="filename"></p></div></dialog>
<script id="catalog-data" type="application/json">__DATA__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('catalog-data').textContent);
const $=id=>document.getElementById(id);const normalize=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').replace(/\s+/g,' ').trim();
let mode='all';const cards=[];const sections=[];const categories=[...new Set(data.map(x=>x.category))];
for(const category of categories){const section=document.createElement('section');const heading=document.createElement('h2');heading.append(document.createTextNode(category));const count=document.createElement('span');count.className='count';heading.append(count);const grid=document.createElement('div');grid.className='grid';section.append(heading,grid);$('sections').append(section);sections.push({category,section,count});
for(const item of data.filter(x=>x.category===category)){const article=document.createElement('article');article.className='card'+(item.kind==='topic'?' topic':'');article.dataset.kind=item.kind;article.dataset.number=item.number;let button;
if(item.image){button=document.createElement('button');button.className='imagebutton';button.setAttribute('aria-label','Увеличить: '+item.number+' '+item.title);const img=document.createElement('img');img.src=item.image;img.alt=(item.kind==='sign'?'Знак ':'Разметка ')+item.number+' — '+item.title;img.decoding='async';button.append(img);button.onclick=()=>showItem(item);article.append(button)}
if(item.number){const number=document.createElement('div');number.className='badge';number.textContent=item.number;article.append(number)}
const title=document.createElement('h3');title.textContent=item.title;article.append(title);
if(item.folk){const folk=document.createElement('p');folk.className='folk';folk.textContent='Народное название: '+item.folk;article.append(folk)}
if(item.description){const desc=document.createElement('p');desc.className='description';desc.textContent=item.description;if(item.kind==='topic'){article.append(desc)}else{const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Описание';details.append(summary,desc);article.append(details)}}
if(item.filename){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Имя файла';const filename=document.createElement('p');filename.className='filename';filename.textContent=item.filename;details.append(summary,filename);article.append(details)}
grid.append(article);cards.push({item,article,search:normalize([item.number,item.title,item.description,item.folk,item.filename,item.category].join(' '))})}}
function matchesMode(item){return mode==='all'||(mode==='sign'?item.kind==='sign':item.kind!=='sign')}
function updateCategories(){const previous=$('category').value;$('category').replaceChildren(new Option('Все категории',''));for(const cat of categories){const items=data.filter(x=>x.category===cat&&matchesMode(x));if(items.length)$('category').add(new Option(cat+' · '+items.length,cat))}if([...$('category').options].some(o=>o.value===previous))$('category').value=previous}
function filter(){const terms=normalize($('search').value).split(' ').filter(Boolean);const category=$('category').value;let n=0;for(const row of cards){row.article.hidden=!(matchesMode(row.item)&&(!category||row.item.category===category)&&terms.every(t=>row.search.includes(t)));if(!row.article.hidden)n++}for(const row of sections){const visible=[...row.section.querySelectorAll('article')].filter(x=>!x.hidden).length;row.section.hidden=!visible;row.count.textContent=String(visible)}$('status').textContent='Показано: '+n+' из '+data.filter(matchesMode).length;$('empty').hidden=n>0}
for(const tab of document.querySelectorAll('.tab'))tab.onclick=()=>{mode=tab.dataset.mode;for(const t of document.querySelectorAll('.tab'))t.setAttribute('aria-pressed',String(t===tab));updateCategories();filter()};$('search').oninput=filter;$('category').onchange=filter;$('descriptions').onchange=()=>{for(const d of document.querySelectorAll('article details'))if(d.querySelector('summary').textContent==='Описание')d.open=$('descriptions').checked};$('print').onclick=()=>window.print();let printOpen=[];window.addEventListener('beforeprint',()=>{printOpen=[...document.querySelectorAll('article details:not([open])')];for(const d of printOpen)d.open=true});window.addEventListener('afterprint',()=>{for(const d of printOpen)d.open=false});
function showItem(item){$('zoom-number').textContent=(item.kind==='sign'?'Знак ':'Разметка ')+item.number;$('zoom-title').textContent=item.title;$('zoom-image').src=item.image;$('zoom-image').alt=item.title;$('zoom-folk').textContent=item.folk?'Народное название: '+item.folk:'';$('zoom-description').textContent=item.description;$('zoom-file').textContent=item.filename;$('zoom').showModal()}
$('zoom').querySelector('.close').onclick=()=>$('zoom').close();$('zoom').onclick=e=>{if(e.target===$('zoom')){const r=$('zoom').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('zoom').close()}};updateCategories();filter();
</script></body></html>'''
out=Path(args.output)
if not out.is_absolute():out=root/out
out.parent.mkdir(parents=True,exist_ok=True)
page=page.replace('__DATA__',payload).replace('__SIGN_COUNT__',str(counts['sign'])).replace('__MARKING_COUNT__',str(counts['marking'])).replace('__DATE__',datetime.now(ZoneInfo('Europe/Minsk')).strftime('%d.%m.%Y'))
out.write_text(page,encoding='utf8')
print(json.dumps({'path':str(out),'cards':len(cards),'signs':counts['sign'],'markings':counts['marking'],'bytes':out.stat().st_size},ensure_ascii=False))
